"""Manually reviewed primary-source additions. Offline reproducible; caches south-r3-search*.json."""
import json,hashlib
from pathlib import Path
P=Path('territory-data/raw'); rows=[]; corrections=[]; events=[]
def add(state,name,seat,url,date,role='Member',note=''):
 rows.append(dict(state=state,name=name,constituency=seat,source_url=url,source_name=state+' State Government',role=role,note='Named serving member in dated official report; partial coverage, not a certified live register. '+note,chamber='State House of Assembly',source_date=date,reference_year=int(date[:4])))
ab='https://abiastate.gov.ng/'
add('Abia','Bar. Anderson Akaliro','Umuahia North',ab+'2027-ohuhu-people-umuahia-endorse-gov-otti-for-second-term-in-office/','2026-02-12',note='Political endorsement is not treated as performance evidence.')
conv=ab+'gov-otti-congratulates-clifford-university-graduates-urges-resilience-financial-discipline/'
add('Abia','Hon. Collins Iheonunekwu','Isiala Ngwa North',conv,'2026-10-25')
add('Abia','Hon. Rowland Chikwendu','Isialangwa South',conv,'2026-10-25',note='Publisher constituency spelling retained; geographic boundary mapping not inferred.')
aiip=ab+'gov-otti-reaffirms-commitment-to-realization-of-aiip-as-new-md-assumes-duty/'
add('Abia','Hon. Godwin Adiele','Ukwa West',aiip,'2026-10-14')
ak='https://news.akwaibomstate.gov.ng/'
local=ak+'akha-oversight-visit-committee-commends-ibesikpo-asutans-developmental-strides/'
env=ak+'akha-environment-committee-commends-eno-over-uyo-village-road-erosion-land-reclamation-project/'
add('Akwa Ibom','Hon. Mfon Idung','Etim Ekpo/Ika',local,'2026-07-14','Chairman, Local Government and Chieftaincy Affairs Committee')
for name,seat,role in [('Hon. Bassey Bassey','Okobo','Chairman, Environment Committee'),('Hon. Udobia Udo','Esit Eket/Ibeno','Vice Chairman, Environment Committee'),('Hon. Ubong Attah','Ibesikpo Asutan','Member'),('Prince Aniefiok Attah','Nsit Atai','Member'),('Hon. Moses Essien','Ibiono Ibom','Member')]:add('Akwa Ibom',name,seat,env,'2026-09-16',role)
an='https://anambrastate.gov.ng/'
law=an+'tag/anambra-assembly-amends-state-local-government-administration-law/'
reconstruction=an+'tag/anambra-assembly-seeks-urgent-reconstruction-of-insecurity-affected-communities/'
support=an+'tag/anambra-speaker-empowers-300/'
add('Anambra','Hon. Jude Akpua','Njikoka II',law,'2026-04-29','Deputy Majority Leader')
add('Anambra','Hon. Golden Iloh','Ihiala II',reconstruction,'2026-06-25',note='This dated plenary report explicitly identifies Ihiala II. An older official carol report instead says Ihiala I; that contradictory label is not adopted.')
add('Anambra','Hon. Ebuka Igwe','Idemili South',reconstruction,'2026-06-25')
corrections=[dict(id='office-003c4d603c94',constituency='Nnewi South II',source_url=law,source_name='Anambra State Government / Ministry of Information',source_date='2026-04-29',note='Explicit manual match to Hon. Johnbosco Akaegbobi; report identifies Nnewi South II. Fills previously missing seat.'),dict(id='office-abff6570661a',constituency='Ogbaru II',source_url=support,source_name='Anambra State Government / Ministry of Information',source_date='2026-04-28',note='Explicit manual match: Speaker Somtochukwu Nkem Udeze in this report is existing Rt. Hon. Somtochukwu Udeze. Report identifies his constituents in Ogbaru II; official Nine Lessons/Carol report also explicitly says representing Ogbaru II. Fills previously missing seat.')]
def oid(state,name):return 'office-'+hashlib.sha256(('State House of Assembly|'+state+'|'+name).encode()).hexdigest()[:12]
def event(key,state,names,date,title,url,summary,category,basis='publication date'):
 events.append(dict(id=key,member_ids=[oid(state,n) for n in names],date=date,reference_year=int(date[:4]),title=title,category=category,source_url=url,source_name=state+' State Government',classification='published',level='state constituency / named representative',status='Officially reported activity',qualification='Official self-report; not an independent outcome audit or complete tenure total. '+('Exact event day is not supplied; publication date shown.' if basis=='publication date' else 'Event date explicitly stated in the report.'),summary=summary,attribution='Named person and constituency manually matched against official source.',date_basis=basis))
event('abia-aiip-site-20261014','Abia',['Hon. Godwin Adiele'],'2026-10-14','Industrial park site engagement',aiip,'Spoke at the project site and requested accelerated implementation. This records engagement and advocacy; industrial park completion and economic impact are not established.','Institutional engagement')
event('akwa-local-oversight-20260714','Akwa Ibom',['Hon. Mfon Idung'],'2026-07-14','Local government oversight visit',local,'Named committee chairman led an oversight visit to Ibesikpo Asutan council and projects. Project delivery is attributed to the council, not personally to the legislator.','Oversight')
event('akwa-environment-20260916','Akwa Ibom',['Hon. Bassey Bassey','Hon. Udobia Udo','Hon. Ubong Attah','Prince Aniefiok Attah','Hon. Moses Essien'],'2026-09-16','Inspection of erosion reclamation works',env,'Named environment committee delegation inspected ongoing Uyo Village Road reclamation works and sought clarification on environmental assessment, quality testing and drainage. This is oversight of ongoing works, not completion or personal project delivery.','Oversight','event date explicitly reported by publisher')
event('anambra-lg-law-20260429','Anambra',['Hon. Jude Akpua','Hon. Johnbosco Akaegbobi'],'2026-04-29','Presentation and seconding of executive amendment',law,'Jude Akpua presented and Johnbosco Akaegbobi seconded the executive local government administration amendment bill. The report describes passage through readings; this does not establish personal authorship or gubernatorial assent.','Legislation')
event('anambra-reconstruction-motion-20260623','Anambra',['Hon. Golden Iloh'],'2026-06-23','Motion for reconstruction of affected communities',reconstruction,'Named mover of the adopted motion seeking a reconstruction programme for communities affected by insecurity. Adoption does not establish that reconstruction was subsequently funded or completed.','Motions','event date explicitly reported by publisher')
event('anambra-reconstruction-debate-20260623','Anambra',['Hon. Ebuka Igwe','Hon. Nonso Atuchukwu','Hon. Emma Nwafor','Hon. Ikenna Ofodeme'],'2026-06-23','Contributions to reconstruction debate',reconstruction,'Named contributors to debate on reconstruction and rehabilitation of communities affected by insecurity. Records debate participation, not sponsorship or completed reconstruction.','Debate','event date explicitly reported by publisher')
event('anambra-udeze-support-20260428','Anambra',['Rt. Hon. Somtochukwu Udeze'],'2026-04-28','Reported constituent equipment and grants programme',support,'Official report describes assistance to over 300 constituents, including persons with disabilities, through equipment, farm inputs and grants. No independently audited beneficiary register or measured income impact is provided.','Constituent support')
def press(state,name,seat,url,date,publisher,role='Member',extra=''):
 add(state,name,seat,url,date,role,extra)
 rows[-1]['source_name']=publisher
 rows[-1]['note']='Named serving member in dated reporting; partial coverage, not a certified live register. '+extra
tax='https://businessday.ng/life/article/enugu-assembly-passes-bill-to-harmonise-taxes-ban-illegal-roadblocks/'
for name,seat in [('Hon. Iloabuchi Aniagu','Nkanu West'),('Hon. Malachy Onyechi','Nsukka West'),('Hon. Okey Mbah','Nkanu East'),('Hon. Raymond Ugwu',None)]:
 press('Enugu',name,seat,tax,'2026-03-15','BusinessDay',extra='Constituency stated by publisher.' if seat else 'Report identifies lawmaker but not seat; no seat inferred.')
interview='https://enugumediavillage.com/2026/08/25/accountability-and-engagement-discussion-at-enugu-state-house-of-assembly-complex/'
for name,seat,role in [('Hon. Ejike Jude Eze','Igboeze North I','Chief Whip'),('Hon. Hyginus Osita Okoh','Enugu East Urban','Member'),('Rt. Hon. Chima Obieze','Ezeagu','Member')]:
 press('Enugu',name,seat,interview,'2026-08-25','Enugu Media Village',role,'First-hand report by the organisation conducting the interviews. Publisher seat label retained; urban/rural labels not automatically mapped to numbered constituencies.')
press('Enugu','Hon. Princess Obiagulu Ugwu','Enugu South Rural','https://blueprint.ng/2027-elections-enugu-lawmaker-flags-off-campaign-pledges-people-centred-engagement/','2026-09-11','Blueprint Newspapers','Deputy Chief Whip','Explicitly described as serving member, not inferred solely from candidacy. Campaign launch not treated as performance. Publisher seat label retained.')
press('Bayelsa','Hon. Living Mitin','Ekeremor II','https://thenationonlineng.net/ndc-founding-member-defects-to-apc-in-bayelsa/','2026-06-29','The Nation',extra='Named current representative; party reception is not performance evidence.')
police='https://punchng.com/bayelsa-assembly-approves-state-police-introduces-two-bills/'
press('Bayelsa','Rt. Hon. Michael Ogbere',None,police,'2026-10-22','Punch Newspapers','Deputy Speaker','Named deputy speaker standing in for the speaker. Source supplies no seat; no seat inferred.')
recess='https://punchng.com/delta-assembly-begins-recess-speaker-urges-constituency-visits/'
press('Delta','Mr Emeka Nwaobi',None,recess,'2026-07-23','Punch Newspapers','House Leader','Source identifies leadership but does not supply a constituency; no seat inferred.')
press('Delta','Mr Pereotu Oloye','Burutu II',recess,'2026-07-23','Punch Newspapers')
press('Delta','Hon. Ferguson Onwo','Isoko South II','https://punchng.com/delta-speaker-deputy-others-clinch-apc-assembly-tickets/','2026-05-20','Punch Newspapers',extra='Specifically identified as incumbent lawmaker. Other candidates in the article not imported merely for winning a primary.')
corrections.append(dict(id='office-58f9dec214d5',constituency='Warri South West',source_url='https://deltaprideng.com/2026/07/25/a-pause-before-the-final-lap-under-guwor-8th-delta-assembly-begins-last-recess/',source_name='Delta Pride / Nkem Nwaeke, Chief Press Secretary to the Speaker',source_date='2026-07-25',note='Explicit manual match: Rt. Hon. Emomotimi Dennis Guwor is existing Rt. Hon. Emomotimi Guwor. Speaker chief press secretary identifies current constituency. Official Delta profile also lists Warri South-west, but its February 2024 date is not treated as a current roster.'))
corrections.append(dict(id='office-9a48368693e7',constituency='Brass III',source_url='https://independent.ng/2027-bayelsa-speaker-wins-apc-primary-deputy-loses-return-ticket/',source_name='Independent Newspapers',source_date='2026-05-21',note='Explicit manual match of Speaker Abraham Ngobere (publisher spelling) to existing Speaker Abraham Ingobere. Report describes his bid to return for a fifth tenure in Brass Constituency 3; not importing newly nominated candidates as incumbents.'))
event('enugu-tax-debate-20260315','Enugu',['Hon. Iloabuchi Aniagu','Hon. Malachy Onyechi','Hon. Okey Mbah','Hon. Raymond Ugwu'],'2026-03-15','Contributions to tax harmonisation debate',tax,'Report attributes contributions on tax harmonisation, public awareness and enforcement penalties to these named members. Records debate participation, not bill authorship, assent or realised revenue gains.','Debate')
events[-1].update(source_name='BusinessDay',status='Published news report',qualification='Dated reporting of named contributions; not a complete legislative total or independent outcome audit. Publication date shown; exact plenary date not supplied in this source.')
event('enugu-accountability-interviews-20260824','Enugu',['Hon. Ejike Jude Eze','Hon. Hyginus Osita Okoh','Rt. Hon. Chima Obieze'],'2026-08-24','Participation in accountability interviews',interview,'The organising media outlet reports interviewing these three representatives at the Assembly complex about legislation, constituency interventions and public engagement. Participation is documented; no unverified performance totals from interview claims are assigned.','Public engagement','event date explicitly reported by publisher')
events[-1].update(source_name='Enugu Media Village',status='First-hand organiser report',qualification='First-hand report by the organisation conducting the interviews, not an independent audit of legislators’ claimed achievements. Event date explicitly stated as 24 August.')
event('bayelsa-deputy-plenary-20261022','Bayelsa',['Rt. Hon. Michael Ogbere'],'2026-10-22','Deputy speaker representation at constitutional amendment plenary',police,'Report names the deputy speaker representing the speaker during the assembly consideration of a state police amendment. Collective approval is not attributed as personal bill sponsorship, and does not establish that the constitutional amendment process was completed.','Legislative proceedings')
events[-1].update(source_name='Punch Newspapers',status='Published news report',qualification='Named-person reporting, not a complete attendance record or independent outcome audit. Publication date shown; exact plenary date not supplied.')
for suffix,data in [('additions',rows),('corrections',corrections),('activity',events)]:P.joinpath('southern-round3-'+suffix+'.json').write_text(json.dumps(data,indent=2)+'\n')
assert len({(r['state'],r['name']) for r in rows})==len(rows)
print({'additions':len(rows),'corrections':len(corrections),'activity':len(events)})
